import { useEffect } from "react";

const GOOGLE_TRANSLATE_SCRIPT_ID = "google-translate-script";

const waitForTranslateCombo = () =>
  new Promise((resolve) => {
    const existing = document.querySelector(".goog-te-combo");
    if (existing) {
      resolve(existing);
      return;
    }

    let attempts = 0;
    const interval = window.setInterval(() => {
      const combo = document.querySelector(".goog-te-combo");
      attempts += 1;
      if (combo || attempts > 80) {
        window.clearInterval(interval);
        resolve(combo);
      }
    }, 125);
  });

const applyGoogleLanguage = async (languageCode) => {
  if (!languageCode) return;

  if (languageCode === "en") {
    const restoreLink = document.querySelector(".goog-te-banner-frame");
    const combo = document.querySelector(".goog-te-combo");
    if (combo) {
      combo.value = "";
      combo.dispatchEvent(new Event("change"));
    }
    if (!restoreLink) {
      document.cookie = "googtrans=; expires=Thu, 01 Jan 1970 00:00:00 UTC; path=/;";
      document.cookie = "googtrans=; expires=Thu, 01 Jan 1970 00:00:00 UTC; path=/; domain=." + window.location.hostname;
    }
    return;
  }

  const combo = await waitForTranslateCombo();
  if (!combo) return;

  combo.value = languageCode;
  combo.dispatchEvent(new Event("change"));
};

export default function GoogleTranslateBridge() {
  useEffect(() => {
    window.googleTranslateElementInit = () => {
      if (!window.google?.translate?.TranslateElement) return;

      new window.google.translate.TranslateElement(
        {
          pageLanguage: "en",
          includedLanguages: "en,hi,mr,te,ta,bn,kn",
          autoDisplay: false,
        },
        "google_translate_element"
      );

      applyGoogleLanguage(localStorage.getItem("cropconnect-language") || "en");
    };

    if (!document.getElementById(GOOGLE_TRANSLATE_SCRIPT_ID)) {
      const script = document.createElement("script");
      script.id = GOOGLE_TRANSLATE_SCRIPT_ID;
      script.src = "https://translate.google.com/translate_a/element.js?cb=googleTranslateElementInit";
      script.async = true;
      document.body.appendChild(script);
    } else {
      applyGoogleLanguage(localStorage.getItem("cropconnect-language") || "en");
    }

    const handleLanguageChange = (event) => {
      applyGoogleLanguage(event.detail?.language || "en");
    };

    window.addEventListener("cropconnect-language-change", handleLanguageChange);
    return () => {
      window.removeEventListener("cropconnect-language-change", handleLanguageChange);
    };
  }, []);

  return <div id="google_translate_element" className="hidden" aria-hidden="true" />;
}
